#include <stdio.h>

#define MAX_MARK 9

void print_array(const int a[], int n) {
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
}

void counting_sort(int a[], int n) {
    int count[MAX_MARK + 1] = {0};

    for (int i = 0; i < n; i++)
        count[a[i]]++;

    int k = 0;
    for (int v = 0; v <= MAX_MARK; v++) {
        while (count[v] > 0) {
            a[k++] = v;
            count[v]--;
        }
    }
}

int main(void) {
    int marks[] = {5, 2, 9, 1, 6, 3};
    int n = sizeof(marks) / sizeof(marks[0]);

    counting_sort(marks, n);
    print_array(marks, n);
    return 0;
}

